    profile = {
        'Name': f'{BRAND_TITLE} — Россия', 'GlobalProxy': 'true',
        'RemoteDNSType': 'DoU',
        'RemoteDNSDomain': '',
        'RemoteDNSIP': '1.1.1.1',
        'DomesticDNSType': 'DoU', 'DomesticDNSDomain': '', 'DomesticDNSIP': '77.88.8.8',
        'Geoipurl': '', 'Geositeurl': '', 'LastUpdated': '1792022400',
        'DnsHosts': {},
        'DirectSites': ['domain:' + domain for domain in DIRECT_DOMAINS],
        'DirectIp': DIRECT_IPS,
        'ProxySites': [], 'ProxyIp': [], 'BlockSites': [], 'BlockIp': [],
        'DomainStrategy': 'AsIs', 'FakeDNS': 'false',
    }
    encoded = base64.b64encode(json.dumps(profile, ensure_ascii=False,
                                         separators=(',', ':')).encode()).decode()
    return 'happ://routing/onadd/' + encoded


def build_native_subscription(encoded_payload):
    """Emit explicit Xray JSON; never rely on Happ's URI/DNS/geo defaults."""
    configs = []
    for line in base64.b64decode(encoded_payload, validate=True).decode().splitlines():
        parts = urlsplit(line)
        if parts.scheme != 'vless' or not parts.username or not parts.hostname or not parts.port:
            raise ValueError('Expected an authenticated VLESS profile')
        query = {k: v[0] for k, v in parse_qs(parts.query).items()}
        network = query.get('type', 'tcp')
        security = query.get('security')
        if security not in ('tls', 'reality') or network not in ('tcp', 'ws'):
            raise ValueError('Unsupported protected transport')
        protected = {'serverName': query['sni'],
                     'fingerprint': 'safari' if security == 'tls' else query.get('fp', 'chrome')}
        if query.get('alpn'):
            protected['alpn'] = query['alpn'].split(',')
        if security == 'reality':
            protected.update(publicKey=query['pbk'], shortId=query['sid'], spiderX=query.get('spx', '/'))
        else:
            protected['allowInsecure'] = False
        stream = {'network': network, 'security': security, security + 'Settings': protected}
        if network == 'ws':
            stream['wsSettings'] = {'path': query.get('path', '/'), 'headers': {'Host': query.get('host', query['sni'])}}
        proxy = {
            'tag': 'proxy', 'protocol': 'vless',
            'settings': {'vnext': [{'address': parts.hostname, 'port': parts.port,
                                   'users': [{'id': parts.username, 'encryption': 'none', 'flow': query.get('flow', '')}]}]},
            'streamSettings': stream, 'mux': {'enabled': False},
        }
        sites = ['domain:' + domain for domain in DIRECT_DOMAINS]
        configs.append({
            'remarks': unquote(parts.fragment), 'log': {'loglevel': 'warning'},
            'dns': {'servers': ['1.1.1.1', '1.0.0.1',
                                {'address': '77.88.8.8', 'domains': sites, 'skipFallback': True}],
                    'queryStrategy': 'UseIPv4', 'tag': 'dns-query'},
            'inbounds': [
                {'tag': 'socks', 'listen': '127.0.0.1', 'port': 10808, 'protocol': 'socks',
                 'settings': {'auth': 'noauth', 'udp': True},
                 'sniffing': {'enabled': True, 'destOverride': ['http', 'tls'], 'routeOnly': True}},
                {'tag': 'http', 'listen': '127.0.0.1', 'port': 10809, 'protocol': 'http', 'settings': {},
                 'sniffing': {'enabled': True, 'destOverride': ['http', 'tls'], 'routeOnly': True}},
            ],
            'outbounds': [proxy,
                          {'tag': 'direct', 'protocol': 'freedom', 'settings': {'domainStrategy': 'UseIPv4'}},
                          {'tag': 'block', 'protocol': 'blackhole'},
                          {'tag': 'dns-out', 'protocol': 'dns', 'settings': {'network': 'tcp', 'address': '1.1.1.1', 'port': 53},
                           'streamSettings': {'sockopt': {'dialerProxy': 'proxy'}}}],
            'routing': {'domainStrategy': 'AsIs', 'rules': [
                {'type': 'field', 'ip': ['77.88.8.8'], 'port': '53', 'outboundTag': 'direct'},
                {'type': 'field', 'inboundTag': ['dns-query'], 'outboundTag': 'proxy'},
                {'type': 'field', 'port': '53', 'outboundTag': 'dns-out'},
                {'type': 'field', 'domain': sites, 'outboundTag': 'direct'},
                {'type': 'field', 'ip': DIRECT_IPS, 'outboundTag': 'direct'},
                {'type': 'field', 'network': 'tcp,udp', 'outboundTag': 'proxy'},
            ]},
        })
    if not configs:
        raise ValueError('No protected VPN profiles')
    configs.sort(key=lambda config: 0 if config['outbounds'][0]['streamSettings']['security'] == 'tls' else 1)
    return configs


