async def handle_subscription(request: web.Request) -> web.Response:
    token = request.match_info.get("token", "")
    database_module = request.app[DATABASE_KEY]
    user = database_module.get_user_by_subscription_token(token)
    if not user or not user.get("vpn_uuid"):
        return _not_found()

    try:
        nodes = list(request.app[NODE_PROVIDER_KEY]())
        if user.get('device_id'):
            nodes = [node for node in nodes if node.key in user['node_keys']]
            from device_service import _target
            factory = request.app[DEVICE_CLIENT_FACTORY_KEY]
            for node in nodes:
                if user['node_targets'].get(node.key) != _target(node, factory(node.key)):
                    return web.Response(status=503, text='Temporarily unavailable', headers={'Cache-Control': 'no-store'})
        payload = build_subscription_payload(
            user["vpn_uuid"], user.get("primary_node") or user.get("server"), nodes
        )
    except Exception:
        logger.exception("Unable to build subscription")
        return web.Response(status=503, text="Temporarily unavailable")

    upload = int(user.get("traffic_up") or 0)
    download = int(user.get("traffic_down") or 0)
    headers = {
        "Cache-Control": "no-store",
        "profile-update-interval": "6",
        "profile-title": BRAND_TITLE,
        "isp-name": BRAND_TITLE,
        "isp-url": request.app[PUBLIC_BASE_URL_KEY],
    }
    if not user.get('device_id') or all(user.get(k) is not None for k in ('traffic_up', 'traffic_down')):
        headers['subscription-userinfo'] = f'upload={upload}; download={download}'
    return web.Response(
        text=payload,
        content_type="text/plain",
        headers=headers,
    )


async def handle_happ_subscription(request: web.Request) -> web.Response:
    response = await handle_subscription(request)
    if response.status != 200:
        return response
    try:
        configs = build_native_subscription(response.text)
    except (ValueError, KeyError, UnicodeError):
        logger.error('Unable to build Happ native subscription')
        return web.Response(status=503, text='Temporarily unavailable', headers={'Cache-Control': 'no-store'})
    headers = response.headers.copy()
    headers.pop('Content-Type', None)
    headers.pop('Content-Length', None)
    headers['routing'] = routing_link()
    return web.json_response(configs, headers=headers)


